-- Recruitment ATS — reference schema (PostgreSQL 16)
--
-- Design status: TARGET. This file is the reference the EF Core migrations must
-- produce; it is documented in docs/07-database-design.md.
--
-- Conventions
--   * Primary keys are UUIDs generated by the application (UUIDv7); the default
--     below is only for manual inserts.
--   * All timestamps are timestamptz in UTC.
--   * Enumerations are text columns with CHECK constraints (easier to evolve with
--     EF Core migrations than native enum types).
--   * row_version columns are not declared: EF Core maps PostgreSQL's system
--     column xmin as the optimistic concurrency token.

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------------------
-- Identity and access
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email               varchar(254) NOT NULL,
    password_hash       text NOT NULL,
    full_name           varchar(120) NOT NULL,
    phone               varchar(20),
    avatar_url          varchar(500),
    timezone            varchar(64) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
    role                varchar(20) NOT NULL
                        CHECK (role IN ('ADMIN', 'HR_MANAGER', 'RECRUITER', 'INTERVIEWER')),
    is_active           boolean NOT NULL DEFAULT true,
    failed_login_count  integer NOT NULL DEFAULT 0,
    locked_until        timestamptz,
    last_login_at       timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX ux_users_email ON users (lower(email));

CREATE TABLE refresh_tokens (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash      char(64) NOT NULL UNIQUE,          -- SHA-256 hex of the opaque token
    family_id       uuid NOT NULL,                     -- all rotations of one login
    expires_at      timestamptz NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    revoked_at      timestamptz,
    replaced_by_id  uuid REFERENCES refresh_tokens (id),
    created_ip      inet,
    user_agent      varchar(300)
);
CREATE INDEX ix_refresh_tokens_user ON refresh_tokens (user_id) WHERE revoked_at IS NULL;
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (family_id);

CREATE TABLE departments (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        varchar(100) NOT NULL UNIQUE,
    is_active   boolean NOT NULL DEFAULT true,
    sort_order  integer NOT NULL DEFAULT 0
);

-- ---------------------------------------------------------------------------
-- Positions and job posts
-- ---------------------------------------------------------------------------

CREATE SEQUENCE position_code_seq START 1;

CREATE TABLE positions (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code              varchar(12) NOT NULL UNIQUE
                      DEFAULT 'JOB-' || lpad(nextval('position_code_seq')::text, 3, '0'),
    title             varchar(150) NOT NULL,
    department_id     uuid NOT NULL REFERENCES departments (id),
    location          varchar(100) NOT NULL,
    employment_type   varchar(20) NOT NULL
                      CHECK (employment_type IN ('FULL_TIME', 'PART_TIME', 'CONTRACT', 'INTERNSHIP')),
    level             varchar(20) NOT NULL
                      CHECK (level IN ('INTERN', 'FRESHER', 'JUNIOR', 'MIDDLE', 'SENIOR', 'LEAD', 'MANAGER')),
    headcount         integer NOT NULL CHECK (headcount >= 1),
    target_hire_date  date NOT NULL,
    description       text NOT NULL,                   -- internal job description
    status            varchar(10) NOT NULL DEFAULT 'DRAFT'
                      CHECK (status IN ('DRAFT', 'OPEN', 'CLOSED')),
    criteria_version  integer NOT NULL DEFAULT 1,
    owner_id          uuid NOT NULL REFERENCES users (id),
    created_by        uuid NOT NULL REFERENCES users (id),
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    closed_at         timestamptz
);
CREATE INDEX ix_positions_status ON positions (status, department_id);
CREATE INDEX ix_positions_owner ON positions (owner_id);

-- Criteria are versioned: editing criteria inserts rows with a new version and
-- leaves old rows for the analyses and scorecards that reference them (US06).
CREATE TABLE position_criteria (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    position_id  uuid NOT NULL REFERENCES positions (id) ON DELETE CASCADE,
    version      integer NOT NULL,
    name         varchar(150) NOT NULL,
    description  varchar(500),
    type         varchar(15) NOT NULL CHECK (type IN ('MUST_HAVE', 'NICE_TO_HAVE')),
    weight       smallint NOT NULL CHECK (weight BETWEEN 1 AND 5),
    sort_order   integer NOT NULL DEFAULT 0
);
CREATE INDEX ix_position_criteria_version ON position_criteria (position_id, version);

CREATE TABLE job_posts (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    position_id      uuid NOT NULL UNIQUE REFERENCES positions (id) ON DELETE CASCADE,
    slug             varchar(120) NOT NULL UNIQUE,
    title            varchar(150) NOT NULL,
    location         varchar(100) NOT NULL,
    employment_type  varchar(20) NOT NULL
                     CHECK (employment_type IN ('FULL_TIME', 'PART_TIME', 'CONTRACT', 'INTERNSHIP')),
    level            varchar(20) NOT NULL
                     CHECK (level IN ('INTERN', 'FRESHER', 'JUNIOR', 'MIDDLE', 'SENIOR', 'LEAD', 'MANAGER')),
    salary_min       bigint CHECK (salary_min >= 0),
    salary_max       bigint,
    salary_currency  char(3) NOT NULL DEFAULT 'VND',
    salary_visible   boolean NOT NULL DEFAULT false,
    summary          varchar(300),
    description      text NOT NULL,
    requirements     text NOT NULL,
    benefits         text,
    closing_date     date,
    status           varchar(12) NOT NULL DEFAULT 'DRAFT'
                     CHECK (status IN ('DRAFT', 'PUBLISHED', 'UNPUBLISHED')),
    published_at     timestamptz,
    published_by     uuid REFERENCES users (id),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CHECK (salary_max IS NULL OR salary_min IS NULL OR salary_max >= salary_min)
);
CREATE INDEX ix_job_posts_published ON job_posts (status, closing_date) WHERE status = 'PUBLISHED';

-- ---------------------------------------------------------------------------
-- Candidates, consent, CV files
-- ---------------------------------------------------------------------------

CREATE TABLE candidates (
    id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    full_name                varchar(120) NOT NULL,
    email                    varchar(254),
    email_normalized         varchar(254),             -- lower-case, trimmed (BR-06)
    email_invalid            boolean NOT NULL DEFAULT false,
    phone                    varchar(20),
    phone_normalized         varchar(15),              -- E.164 digits (BR-06)
    notes                    text,
    skills                   text[] NOT NULL DEFAULT '{}',  -- from the latest completed analysis, for pool search
    pool_consent_at          timestamptz,
    pool_consent_expires_at  timestamptz,              -- in the talent pool while > now() (BR-24)
    pool_renewal_sent_at     timestamptz,
    consent_token_version    integer NOT NULL DEFAULT 1,  -- bump to invalidate old consent links
    last_activity_at         timestamptz NOT NULL DEFAULT now(),
    is_anonymized            boolean NOT NULL DEFAULT false,
    anonymized_at            timestamptz,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    CHECK (email IS NOT NULL OR phone IS NOT NULL OR is_anonymized)
);
CREATE UNIQUE INDEX ux_candidates_email ON candidates (email_normalized)
    WHERE email_normalized IS NOT NULL AND NOT is_anonymized;
CREATE UNIQUE INDEX ux_candidates_phone ON candidates (phone_normalized)
    WHERE phone_normalized IS NOT NULL AND NOT is_anonymized;
CREATE INDEX ix_candidates_pool ON candidates (pool_consent_expires_at)
    WHERE pool_consent_expires_at IS NOT NULL;
CREATE INDEX ix_candidates_skills ON candidates USING gin (skills);

-- Append-only consent history (BR-19, BR-24, US31).
CREATE TABLE consent_records (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    candidate_id    uuid NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
    application_id  uuid,                                -- FK added after applications
    purpose         varchar(20) NOT NULL
                    CHECK (purpose IN ('PRIVACY_POLICY', 'SUBMISSION_BASIS', 'TALENT_POOL')),
    action          varchar(12) NOT NULL
                    CHECK (action IN ('GRANTED', 'RENEWED', 'WITHDRAWN', 'EXPIRED', 'ERASED')),
    policy_version  varchar(20),
    channel         varchar(20) NOT NULL
                    CHECK (channel IN ('CAREER_SITE', 'CONSENT_LINK', 'MAILBOX', 'MANUAL', 'IMPORT', 'TALENT_POOL', 'SYSTEM')),
    ip_address      inet,
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_consent_records_candidate ON consent_records (candidate_id, created_at DESC);

CREATE TABLE cv_files (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    candidate_id       uuid NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
    storage_key        varchar(200) NOT NULL UNIQUE,     -- path inside the CV file store
    original_name      varchar(255) NOT NULL,
    content_type       varchar(100) NOT NULL
                       CHECK (content_type IN ('application/pdf',
                              'application/vnd.openxmlformats-officedocument.wordprocessingml.document')),
    size_bytes         integer NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 10485760),  -- BR-15
    sha256             char(64) NOT NULL,
    extracted_text     text,                             -- cleared when the file is deleted
    uploaded_by        uuid REFERENCES users (id),       -- null for public and mailbox intake
    uploaded_at        timestamptz NOT NULL DEFAULT now(),
    deleted_at         timestamptz                       -- BR-17, BR-24: file removed from storage
);
CREATE INDEX ix_cv_files_candidate ON cv_files (candidate_id);

-- ---------------------------------------------------------------------------
-- Intake staging: mailbox and bulk import
-- ---------------------------------------------------------------------------

CREATE TABLE import_batches (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    position_id          uuid NOT NULL REFERENCES positions (id),
    status               varchar(10) NOT NULL DEFAULT 'PREVIEWED'
                         CHECK (status IN ('PREVIEWED', 'COMPLETED', 'EXPIRED')),
    excel_file_name      varchar(255) NOT NULL,
    zip_file_name        varchar(255) NOT NULL,
    staging_key          varchar(200) NOT NULL,          -- temporary folder in the file store
    total_rows           integer NOT NULL CHECK (total_rows BETWEEN 1 AND 200),  -- BR-16
    valid_rows           integer NOT NULL,
    created_count        integer NOT NULL DEFAULT 0,
    send_receipt_emails  boolean NOT NULL DEFAULT true,
    preview_rows         jsonb NOT NULL,                 -- [{row, fullName, email, phone, source, cvFile, status, errors[]}]
    created_by           uuid NOT NULL REFERENCES users (id),
    created_at           timestamptz NOT NULL DEFAULT now(),
    completed_at         timestamptz,
    expires_at           timestamptz NOT NULL            -- previews expire after 24 h
);

CREATE TABLE inbox_items (
    id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    message_id            varchar(300) NOT NULL UNIQUE, -- BR-22 de-duplication
    from_address          varchar(254) NOT NULL,
    from_name             varchar(200),
    subject               varchar(500) NOT NULL DEFAULT '',
    body_preview          varchar(2000),
    received_at           timestamptz NOT NULL,
    status                varchar(14) NOT NULL DEFAULT 'NEEDS_REVIEW'
                          CHECK (status IN ('NEEDS_REVIEW', 'CONVERTED', 'DUPLICATE', 'DISMISSED')),
    detected_position_id  uuid REFERENCES positions (id),
    application_id        uuid,                          -- FK added after applications
    processed_by          uuid REFERENCES users (id),    -- null when converted automatically
    processed_at          timestamptz,
    created_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_inbox_items_status ON inbox_items (status, received_at DESC);

CREATE TABLE inbox_attachments (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    inbox_item_id  uuid NOT NULL REFERENCES inbox_items (id) ON DELETE CASCADE,
    storage_key    varchar(200) NOT NULL UNIQUE,
    file_name      varchar(255) NOT NULL,
    content_type   varchar(100) NOT NULL,
    size_bytes     integer NOT NULL
);

-- ---------------------------------------------------------------------------
-- Applications and pipeline
-- ---------------------------------------------------------------------------

CREATE TABLE applications (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    position_id          uuid NOT NULL REFERENCES positions (id),
    candidate_id         uuid NOT NULL REFERENCES candidates (id),
    stage                varchar(10) NOT NULL DEFAULT 'NEW'
                         CHECK (stage IN ('NEW', 'SCREENING', 'INTERVIEW', 'OFFER', 'HIRED', 'REJECTED')),
    source               varchar(15) NOT NULL
                         CHECK (source IN ('CAREER_SITE', 'LINKEDIN', 'FACEBOOK', 'TOPCV', 'VIETNAMWORKS',
                                           'EMAIL', 'REFERRAL', 'OTHER')),
    source_note          varchar(200),
    intake_channel       varchar(12) NOT NULL
                         CHECK (intake_channel IN ('CAREER_SITE', 'MAILBOX', 'MANUAL', 'IMPORT', 'TALENT_POOL')),
    cover_message        varchar(2000),
    current_cv_file_id   uuid REFERENCES cv_files (id),
    current_analysis_id  uuid,                           -- FK added after cv_analyses
    fit_score            smallint CHECK (fit_score BETWEEN 0 AND 100),  -- effective score, denormalized
    missing_must_have    boolean NOT NULL DEFAULT false,
    rejection_reason     varchar(25)
                         CHECK (rejection_reason IN ('SKILLS_MISMATCH', 'EXPERIENCE_MISMATCH', 'SALARY_MISMATCH',
                                                     'FAILED_INTERVIEW', 'CULTURE_FIT', 'POSITION_FILLED',
                                                     'NO_RESPONSE', 'CANDIDATE_WITHDREW', 'OTHER')),
    rejection_note       varchar(500),
    import_batch_id      uuid REFERENCES import_batches (id),
    applied_at           timestamptz NOT NULL DEFAULT now(),
    stage_changed_at     timestamptz NOT NULL DEFAULT now(),
    closed_at            timestamptz,                    -- time of HIRED or REJECTED
    created_by           uuid REFERENCES users (id),     -- null for public and mailbox intake
    updated_at           timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ux_applications_position_candidate UNIQUE (position_id, candidate_id),  -- BR-06
    CHECK (source <> 'OTHER' OR source_note IS NOT NULL),                              -- BR-18
    CHECK ((stage = 'REJECTED') = (rejection_reason IS NOT NULL))                      -- BR-02
);
CREATE INDEX ix_applications_position_stage ON applications (position_id, stage);
CREATE INDEX ix_applications_candidate ON applications (candidate_id);
CREATE INDEX ix_applications_score ON applications (fit_score DESC NULLS LAST);
CREATE INDEX ix_applications_applied ON applications (applied_at DESC);

ALTER TABLE consent_records
    ADD FOREIGN KEY (application_id) REFERENCES applications (id) ON DELETE SET NULL;
ALTER TABLE inbox_items
    ADD FOREIGN KEY (application_id) REFERENCES applications (id) ON DELETE SET NULL;

CREATE TABLE stage_history (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id    uuid NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    from_stage        varchar(10),                       -- null for the initial NEW entry
    to_stage          varchar(10) NOT NULL,
    rejection_reason  varchar(25),
    note              varchar(500),
    actor_id          uuid REFERENCES users (id),        -- null for system actions (BR-24 deletion)
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_stage_history_application ON stage_history (application_id, created_at);
CREATE INDEX ix_stage_history_report ON stage_history (to_stage, created_at);

-- ---------------------------------------------------------------------------
-- AI screening — cv_analyses is also the Worker's job queue (AD-02)
-- ---------------------------------------------------------------------------

CREATE TABLE cv_analyses (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id     uuid NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    cv_file_id         uuid NOT NULL REFERENCES cv_files (id) ON DELETE CASCADE,
    criteria_version   integer NOT NULL,
    status             varchar(10) NOT NULL DEFAULT 'PENDING'
                       CHECK (status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'OUTDATED')),
    attempt_count      smallint NOT NULL DEFAULT 0,
    available_at       timestamptz NOT NULL DEFAULT now(),  -- next time the Worker may claim it
    locked_until       timestamptz,                          -- lease while PROCESSING
    requested_by       uuid REFERENCES users (id),
    requested_at       timestamptz NOT NULL DEFAULT now(),
    started_at         timestamptz,
    completed_at       timestamptz,
    failure_reason     varchar(500),
    model              varchar(100),
    extracted          jsonb,                             -- {skills[], yearsOfExperience, education[], languages[], summary}
    ai_score           smallint CHECK (ai_score BETWEEN 0 AND 100),
    final_score        smallint CHECK (final_score BETWEEN 0 AND 100),  -- after overrides (BR-12, BR-13)
    missing_must_have  boolean,
    is_overridden      boolean NOT NULL DEFAULT false
);
CREATE INDEX ix_cv_analyses_queue ON cv_analyses (available_at)
    WHERE status IN ('PENDING', 'PROCESSING');
CREATE INDEX ix_cv_analyses_application ON cv_analyses (application_id, requested_at DESC);

ALTER TABLE applications
    ADD FOREIGN KEY (current_analysis_id) REFERENCES cv_analyses (id) ON DELETE SET NULL;

CREATE TABLE analysis_criterion_results (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id     uuid NOT NULL REFERENCES cv_analyses (id) ON DELETE CASCADE,
    criterion_id    uuid NOT NULL REFERENCES position_criteria (id),
    ai_result       varchar(10) NOT NULL
                    CHECK (ai_result IN ('MET', 'PARTIAL', 'NOT_MET', 'UNVERIFIED')),
    ai_quote        varchar(1000),
    ai_explanation  varchar(1000),
    final_result    varchar(10) NOT NULL
                    CHECK (final_result IN ('MET', 'PARTIAL', 'NOT_MET', 'UNVERIFIED')),
    override_reason varchar(500) CHECK (override_reason IS NULL OR char_length(override_reason) >= 10),  -- BR-13
    overridden_by   uuid REFERENCES users (id),
    overridden_at   timestamptz,
    CONSTRAINT ux_analysis_criterion UNIQUE (analysis_id, criterion_id),
    CHECK ((overridden_by IS NULL) = (override_reason IS NULL))
);

-- One row per call to the external AI service (cross-cutting constraint in 03).
CREATE TABLE ai_call_logs (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id    uuid NOT NULL REFERENCES cv_analyses (id) ON DELETE CASCADE,
    attempt        smallint NOT NULL,
    model          varchar(100) NOT NULL,
    started_at     timestamptz NOT NULL,
    duration_ms    integer NOT NULL,
    outcome        varchar(10) NOT NULL CHECK (outcome IN ('SUCCESS', 'TIMEOUT', 'RATE_LIMIT', 'ERROR', 'INVALID')),
    http_status    smallint,
    input_chars    integer NOT NULL,
    input_tokens   integer,
    output_tokens  integer,
    error_message  varchar(1000)
);
CREATE INDEX ix_ai_call_logs_started ON ai_call_logs (started_at DESC);

-- ---------------------------------------------------------------------------
-- Interviews and scorecards
-- ---------------------------------------------------------------------------

CREATE TABLE interviews (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id    uuid NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    round_name        varchar(100) NOT NULL,
    starts_at         timestamptz NOT NULL,
    duration_minutes  smallint NOT NULL CHECK (duration_minutes BETWEEN 15 AND 480),
    location          varchar(200),
    meeting_url       varchar(500),
    status            varchar(10) NOT NULL DEFAULT 'SCHEDULED'
                      CHECK (status IN ('SCHEDULED', 'CANCELLED')),
    cancel_reason     varchar(300),
    created_by        uuid NOT NULL REFERENCES users (id),
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    CHECK (location IS NOT NULL OR meeting_url IS NOT NULL)
);
CREATE INDEX ix_interviews_application ON interviews (application_id);
CREATE INDEX ix_interviews_starts ON interviews (starts_at) WHERE status = 'SCHEDULED';

-- slot duplicates the interview time so the database itself rejects overlapping
-- interviews for one panel member (US14); it is cleared when the interview is cancelled.
CREATE TABLE interview_panelists (
    interview_id  uuid NOT NULL REFERENCES interviews (id) ON DELETE CASCADE,
    user_id       uuid NOT NULL REFERENCES users (id),
    slot          tstzrange,
    PRIMARY KEY (interview_id, user_id),
    CONSTRAINT ex_panelist_overlap EXCLUDE USING gist (user_id WITH =, slot WITH &&) WHERE (slot IS NOT NULL)
);
CREATE INDEX ix_interview_panelists_user ON interview_panelists (user_id);

CREATE TABLE scorecards (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    interview_id     uuid NOT NULL REFERENCES interviews (id) ON DELETE CASCADE,
    interviewer_id   uuid NOT NULL REFERENCES users (id),
    status           varchar(10) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'SUBMITTED')),
    recommendation   varchar(10)
                     CHECK (recommendation IN ('STRONG_YES', 'YES', 'NO', 'STRONG_NO')),
    overall_comment  text,
    submitted_at     timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ux_scorecard_interviewer UNIQUE (interview_id, interviewer_id),
    CHECK (status = 'DRAFT' OR (recommendation IS NOT NULL AND submitted_at IS NOT NULL))
);

CREATE TABLE scorecard_ratings (
    scorecard_id  uuid NOT NULL REFERENCES scorecards (id) ON DELETE CASCADE,
    criterion_id  uuid NOT NULL REFERENCES position_criteria (id),
    rating        smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment       varchar(1000),
    PRIMARY KEY (scorecard_id, criterion_id)
);

-- ---------------------------------------------------------------------------
-- Candidate communication — email_messages is also the Worker's email queue
-- ---------------------------------------------------------------------------

CREATE TABLE email_templates (
    event          varchar(25) PRIMARY KEY
                   CHECK (event IN ('RECEIPT', 'INTERVIEW_INVITATION', 'INTERVIEW_CHANGED', 'INTERVIEW_CANCELLED',
                                    'REJECTION', 'OFFER', 'POOL_RENEWAL', 'CONSENT_CONFIRMATION')),
    delay_minutes  smallint NOT NULL CHECK (delay_minutes IN (0, 10)),  -- BR-23
    subject        varchar(200) NOT NULL,
    body_html      text NOT NULL,
    updated_by     uuid REFERENCES users (id),
    updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE email_messages (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    candidate_id         uuid NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
    application_id       uuid REFERENCES applications (id) ON DELETE CASCADE,  -- null for pool and consent emails
    interview_id         uuid REFERENCES interviews (id) ON DELETE SET NULL,
    event                varchar(25) NOT NULL REFERENCES email_templates (event),
    to_address           varchar(254) NOT NULL,
    subject              varchar(200) NOT NULL,
    body_html            text NOT NULL,
    status               varchar(10) NOT NULL DEFAULT 'PENDING'
                         CHECK (status IN ('PENDING', 'SENDING', 'SENT', 'FAILED', 'CANCELLED')),
    scheduled_at         timestamptz NOT NULL,          -- end of the cancel window
    next_attempt_at      timestamptz NOT NULL,          -- scheduled_at, then retry times (1, 5, 30 min)
    attempt_count        smallint NOT NULL DEFAULT 0,
    last_error           varchar(1000),
    sent_at              timestamptz,
    provider_message_id  varchar(300),
    edited_by            uuid REFERENCES users (id),
    edited_at            timestamptz,
    cancelled_by         uuid REFERENCES users (id),    -- null when cancelled by the system (BR-23)
    cancelled_at         timestamptz,
    cancel_reason        varchar(200),
    created_by           uuid REFERENCES users (id),
    created_at           timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_email_messages_queue ON email_messages (next_attempt_at) WHERE status IN ('PENDING', 'SENDING');
CREATE INDEX ix_email_messages_application ON email_messages (application_id, created_at DESC);
CREATE INDEX ix_email_messages_failed ON email_messages (created_at DESC) WHERE status = 'FAILED';

-- Exactly one row (id = 1). Passwords are encrypted with ASP.NET Data Protection.
CREATE TABLE mail_settings (
    id                       smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    imap_host                varchar(200),
    imap_port                integer CHECK (imap_port BETWEEN 1 AND 65535),
    imap_use_ssl             boolean NOT NULL DEFAULT true,
    imap_username            varchar(254),
    imap_password_encrypted  text,
    imap_folder              varchar(100) NOT NULL DEFAULT 'INBOX',
    mailbox_enabled          boolean NOT NULL DEFAULT false,
    last_poll_at             timestamptz,
    last_poll_status         varchar(500),
    smtp_host                varchar(200),
    smtp_port                integer CHECK (smtp_port BETWEEN 1 AND 65535),
    smtp_security            varchar(10) NOT NULL DEFAULT 'STARTTLS'
                             CHECK (smtp_security IN ('STARTTLS', 'SSL', 'NONE')),
    smtp_username            varchar(254),
    smtp_password_encrypted  text,
    sender_name              varchar(100),
    sender_address           varchar(254),
    reply_to_address         varchar(254),
    updated_by               uuid REFERENCES users (id),
    updated_at               timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Governance
-- ---------------------------------------------------------------------------

CREATE TABLE audit_logs (
    id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    occurred_at  timestamptz NOT NULL DEFAULT now(),
    actor_type   varchar(10) NOT NULL CHECK (actor_type IN ('USER', 'SYSTEM', 'CANDIDATE')),
    actor_id     uuid REFERENCES users (id),
    module       varchar(15) NOT NULL
                 CHECK (module IN ('AUTH', 'POSITION', 'JOB_POST', 'APPLICATION', 'CANDIDATE', 'AI', 'INTERVIEW',
                                   'EMAIL', 'INBOX', 'IMPORT', 'TALENT_POOL', 'REPORT', 'USER', 'SETTINGS', 'CONSENT')),
    action       varchar(20) NOT NULL
                 CHECK (action IN ('LOGIN', 'LOGIN_FAILED', 'LOGOUT', 'CREATE', 'UPDATE', 'STATUS_CHANGE',
                                   'STAGE_CHANGE', 'AI_OVERRIDE', 'PUBLISH', 'UNPUBLISH', 'EXPORT', 'IMPORT',
                                   'ASSIGN', 'DISMISS', 'CANCEL', 'RESEND', 'SUBMIT', 'CONSENT_CHANGE',
                                   'CV_DELETE', 'ANONYMIZE')),
    entity_type  varchar(30),
    entity_id    uuid,
    summary      varchar(300) NOT NULL,
    details      jsonb,                                  -- before/after values; never secrets or CV text
    ip_address   inet,
    trace_id     varchar(64)
);
CREATE INDEX ix_audit_logs_time ON audit_logs (occurred_at DESC);
CREATE INDEX ix_audit_logs_filter ON audit_logs (module, action, occurred_at DESC);
CREATE INDEX ix_audit_logs_actor ON audit_logs (actor_id, occurred_at DESC);
CREATE INDEX ix_audit_logs_entity ON audit_logs (entity_type, entity_id);

-- Talent pool = candidates with active pool consent (BR-24).
CREATE VIEW talent_pool AS
SELECT c.*
FROM candidates c
WHERE NOT c.is_anonymized
  AND c.pool_consent_expires_at > now();
